import{_ as i,o as e,c as o,a4 as n}from"./chunks/framework.vNSRaLQv.js";const p=JSON.parse('{"title":"Windows 再见","description":"","frontmatter":{"title":"Windows 再见","date":"2026-07-12T00:00:00.000Z"},"headers":[],"relativePath":"posts/why-i-quit-windows.md","filePath":"posts/why-i-quit-windows.md"}'),t={name:"posts/why-i-quit-windows.md"};function s(r,a,l,d,h,c){return e(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="windows-再见" tabindex="-1">Windows 再见 <a class="header-anchor" href="#windows-再见" aria-label="Permalink to &quot;Windows 再见&quot;">​</a></h1><h2 id="起因" tabindex="-1">起因 <a class="header-anchor" href="#起因" aria-label="Permalink to &quot;起因&quot;">​</a></h2><p>一块 SSD、一个系统盘、一个只想好好写代码的人。</p><h2 id="过程" tabindex="-1">过程 <a class="header-anchor" href="#过程" aria-label="Permalink to &quot;过程&quot;">​</a></h2><p>想要保护 SSD 减少写入 → 装了 ImDisk RAM 盘 → 设了 TEMP 重定向 → Bun 打包的 opencode 炸了 → 排查半天发现是 ImDisk 兼容性问题 → 提了 issue → 改跑源码 → 发现 gradle 1.6G 缓存还在 C 盘 → yarn 1.2G 缓存在 C 盘 → bun 缓存 526M 在 C 盘 → npm 缓存 7.5G 刚迁走 → 噢还有一个 UTF-8 Beta 搞得老程序乱码 → 还有一个 C:\\Windows\\Temp junction 搞得系统组件异常 → 还有 Clash Verge 日志 symlink 断了直接崩溃 → 还有 EventLog、WMI、WaaSMedic 一堆后台日志在偷偷写 SSD → 还有……</p><p>每一个问题单独看都不大，但加起来就是一个下午接一个下午，一个文档接一个文档。</p><h2 id="核心矛盾" tabindex="-1">核心矛盾 <a class="header-anchor" href="#核心矛盾" aria-label="Permalink to &quot;核心矛盾&quot;">​</a></h2><p>我只是想写代码。但 Windows 让我变成了系统管理员、注册表医生、缓存规划师、symlink 管理员、兼容性测试员。</p><p>每一个工具，要在 Windows 上跑顺，都需要额外的一层配置，额外的一层心智负担。这不是「开箱即用」，这是「开箱即折腾」。</p><h2 id="对比" tabindex="-1">对比 <a class="header-anchor" href="#对比" aria-label="Permalink to &quot;对比&quot;">​</a></h2><ul><li><strong>TEMP 在内存盘上</strong> — Linux: <code>TMPDIR=/tmp</code>，早就有了。Windows: 装 RAM 盘软件 → 改注册表 → 处理一堆兼容性问题</li><li><strong>包管理器缓存</strong> — Linux: <code>~/.cache</code> 统一在 home 下。Windows: 每个软件各玩各的，Local、Roaming、User Profile，NPM/YARN/BUN/PNPM 各占一个坑</li><li><strong>编码</strong> — Linux: UTF-8 从一开始。Windows: ACP=936 还是 65001，两边不讨好</li><li><strong>DLL 加载</strong> — Linux: <code>LD_LIBRARY_PATH</code>，简单直接。Windows: side-by-side、WinSxS、现在 Bun 还要从 TEMP 里 extract DLL，挑 RAM 盘</li><li><strong>符号链接</strong> — Linux: 从 1970 年代就有了，ln -s 完事。Windows: 得管理员权限、分 junction/symlink/hardlink，跨卷还有各种限制</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>Windows 不是不能用，它只是把系统管理的成本转嫁给了用户。</p><p>每一个额外的配置项、每一个兼容性开关、每一个 symlink 的权限问题，都不是 bug，是 feature。每一个都有人在你之前遇到过，每一个都有 StackOverflow 答案，每一个都消耗你 15 分钟到 2 小时不等。</p><p>积少成多。</p><p>我不想再处理这些事情了。我想写代码。</p><h2 id="后续" tabindex="-1">后续 <a class="header-anchor" href="#后续" aria-label="Permalink to &quot;后续&quot;">​</a></h2><ul><li>现有的 R: RAM 盘配置和缓存迁移方案已经写在文档里了</li><li>等这个项目忙完，换 Linux</li></ul><h2 id="最后" tabindex="-1">最后 <a class="header-anchor" href="#最后" aria-label="Permalink to &quot;最后&quot;">​</a></h2><p>Windows 陪伴了很多年。谢谢，但到此为止了。</p>',20)])])}const w=i(t,[["render",s]]);export{p as __pageData,w as default};
